// src/utils/utils.jsx
import * as jsts from 'jsts';   // back to the simple form


/**
 * Clamps a value between a minimum and maximum range.
 *
 * @param {number} value - The value to clamp.
 * @param {number} min - The minimum allowable value.
 * @param {number} max - The maximum allowable value.
 * @returns {number} The clamped value.
 */
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

/**
 * Clamps a point's coordinates to ensure it lies within the canvas boundaries.
 *
 * @param {Object} point - Point object with properties x and y.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Object} Clamped point object with properties x and y.
 */
export function clampPoint(point, width = 800, height = 600) {
  return {
    x: clamp(point.x, 0, width),
    y: clamp(point.y, 0, height),
  };
}

/**
 * Generates a specified number of random lines by selecting two distinct borders and ensuring all intersections lie within the canvas.
 *
 * @param {number} num - Number of lines to generate.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Array} Array of line objects with properties A, B, C, p1, p2.
 */
export function generateRandomLines(num, width = 800, height = 600) {
  const lines = [];
  const borders = ['top', 'bottom', 'left', 'right'];
  const maxAttempts = 1000; // To prevent infinite loops
  let attempts = 0;

  while (lines.length < num && attempts < maxAttempts) {
    attempts += 1;
    // Choose two distinct borders
    const [border1, border2] = getTwoDistinctBorders(borders);

    // Get random points on the selected borders
    const p1 = getRandomPointOnBorder(border1, width, height);
    const p2 = getRandomPointOnBorder(border2, width, height);

    // Calculate line coefficients
    const A = p2.y - p1.y;
    const B = p1.x - p2.x;
    const C = -(A * p1.x + B * p1.y);
    const newLine = { A, B, C, p1, p2 };

    // Check intersections with existing lines
    let isValid = true;
    for (let existingLine of lines) {
      const intersection = getIntersectionPoint(newLine, existingLine);
      if (intersection) {
        if (!isPointInCanvas(intersection, width, height)) {
          isValid = false;
          break;
        }
      }
      // If lines are parallel, no intersection; continue
    }

    if (isValid) {
      lines.push(newLine);
    }
  }

  if (attempts === maxAttempts) {
    console.warn('Max attempts reached while generating lines. Some lines may not have been generated.');
  }

  return lines;
}

/**
 * Selects two distinct borders from the list.
 *
 * @param {Array} borders - Array of border names.
 * @returns {Array} Array containing two distinct border names.
 */
function getTwoDistinctBorders(borders) {
  const shuffled = borders.sort(() => 0.5 - Math.random());
  return [shuffled[0], shuffled[1]];
}

/**
 * Generates a random point on a given border.
 *
 * @param {string} border - One of 'top', 'bottom', 'left', 'right'.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Object} Point object with properties x and y.
 */
function getRandomPointOnBorder(border, width, height) {
  switch (border) {
    case 'top':
      return { x: Math.random() * width, y: 0 };
    case 'bottom':
      return { x: Math.random() * width, y: height };
    case 'left':
      return { x: 0, y: Math.random() * height };
    case 'right':
      return { x: width, y: Math.random() * height };
    default:
      return { x: 0, y: 0 };
  }
}

/**
 * Calculates the intersection point of two lines.
 *
 * @param {Object} line1 - First line with properties A, B, C.
 * @param {Object} line2 - Second line with properties A, B, C.
 * @returns {Object|null} Intersection point with properties x and y, or null if parallel.
 */
export function getIntersectionPoint(line1, line2) {
  const { A: A1, B: B1, C: C1 } = line1;
  const { A: A2, B: B2, C: C2 } = line2;

  const denominator = A1 * B2 - A2 * B1;
  if (Math.abs(denominator) < 1e-10) {
    // Lines are parallel or coincident
    return null;
  }

  const x = (B1 * C2 - B2 * C1) / denominator;
  const y = (A2 * C1 - A1 * C2) / denominator;

  return { x, y };
}

/**
 * Checks if a point is within the canvas boundaries.
 *
 * @param {Object} point - Point object with properties x and y.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {boolean} True if inside, else false.
 */
export function isPointInCanvas(point, width = 800, height = 600) {
  return (
    point.x >= 0 &&
    point.x <= width &&
    point.y >= 0 &&
    point.y <= height
  );
}

/**
 * Finds all valid triangles formed by three lines without any lines passing through their interiors.
 *
 * @param {Array} lines - Array of line objects.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Array} Array of triangle objects with points p1, p2, p3.
 */
export function findTriangles(lines, width = 800, height = 600) {
  const triangles = [];
  const epsilon = 1e-6; // Small value to account for floating-point precision

  for (let i = 0; i < lines.length; i++) {
    for (let j = i + 1; j < lines.length; j++) {
      for (let k = j + 1; k < lines.length; k++) {
        const line1 = lines[i];
        const line2 = lines[j];
        const line3 = lines[k];

        const p1 = getIntersectionPoint(line1, line2);
        const p2 = getIntersectionPoint(line1, line3);
        const p3 = getIntersectionPoint(line2, line3);

        if (
          p1 &&
          p2 &&
          p3 &&
          isPointInCanvas(p1, width, height) &&
          isPointInCanvas(p2, width, height) &&
          isPointInCanvas(p3, width, height) &&
          isValidTriangle(p1, p2, p3)
        ) {
          const triangle = { p1, p2, p3 };

          // Check if any other line intersects the interior of the triangle
          let hasInteriorLine = false;
          for (let m = 0; m < lines.length; m++) {
            if (m === i || m === j || m === k) continue;
            const currentLine = lines[m];
            const intersections = getLineIntersectionsWithPolygon(currentLine, [p1, p2, p3]);
            if (intersections.length >= 2) {
              // Line passes through the interior
              hasInteriorLine = true;
              break;
            }
          }

          if (!hasInteriorLine) {
            triangles.push(triangle);
          }
        }
      }
    }
  }

  return triangles;
}

/**
 * Finds all triangles derived from each 4-tuple of lines by considering all 3-line combinations.
 * These triangles are used for quadrilateral detection and are colored regardless of line intersections.
 *
 * @param {Array} lines - Array of line objects.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Array} Array of triangle objects with points p1, p2, p3.
 */
export function findQuadrilateralTriangles(lines, width = 800, height = 600) {
  const quadrilateralTriangles = [];

  // Generate all unique 4-tuples of lines
  for (let i = 0; i < lines.length; i++) {
    for (let j = i + 1; j < lines.length; j++) {
      for (let k = j + 1; k < lines.length; k++) {
        for (let l = k + 1; l < lines.length; l++) {
          const fourLines = [lines[i], lines[j], lines[k], lines[l]];
          // Generate all 4 choose 3 = 4 triangles from the 4 lines
          const combinations = get3LineCombinations(fourLines);
          combinations.forEach((combo) => {
            const [line1, line2, line3] = combo;
            const p1 = getIntersectionPoint(line1, line2);
            const p2 = getIntersectionPoint(line1, line3);
            const p3 = getIntersectionPoint(line2, line3);

            if (
              p1 &&
              p2 &&
              p3 &&
              isPointInCanvas(p1, width, height) &&
              isPointInCanvas(p2, width, height) &&
              isPointInCanvas(p3, width, height) &&
              isValidTriangle(p1, p2, p3)
            ) {
              const triangle = { p1, p2, p3 };
              quadrilateralTriangles.push(triangle);
            }
          });
        }
      }
    }
  }

  return quadrilateralTriangles;
}

/**
 * Generates all 3-line combinations from a set of 4 lines.
 *
 * @param {Array} fourLines - Array containing exactly 4 line objects.
 * @returns {Array} Array of arrays, each containing 3 line objects.
 */
function get3LineCombinations(fourLines) {
  const combinations = [];
  for (let i = 0; i < fourLines.length; i++) {
    for (let j = i + 1; j < fourLines.length; j++) {
      for (let k = j + 1; k < fourLines.length; k++) {
        combinations.push([fourLines[i], fourLines[j], fourLines[k]]);
      }
    }
  }
  return combinations;
}

/**
 * Validates if three points form a non-colinear triangle.
 *
 * @param {Object} p1 - Point with properties x and y.
 * @param {Object} p2 - Point with properties x and y.
 * @param {Object} p3 - Point with properties x and y.
 * @returns {boolean} True if valid triangle, else false.
 */
function isValidTriangle(p1, p2, p3) {
  const area = Math.abs(
    (p1.x * (p2.y - p3.y) +
      p2.x * (p3.y - p1.y) +
      p3.x * (p1.y - p2.y)) / 2
  );
  return area > 1e-6; // Threshold to avoid floating-point precision issues
}

/**
 * Checks if a point lies on a line segment defined by two points.
 *
 * @param {Object} point - Point with properties x and y.
 * @param {Object} start - Start point of the segment.
 * @param {Object} end - End point of the segment.
 * @returns {boolean} True if on segment, else false.
 */
function isPointOnLineSegment(point, start, end) {
  const minX = Math.min(start.x, end.x) - 1e-6;
  const maxX = Math.max(start.x, end.x) + 1e-6;
  const minY = Math.min(start.y, end.y) - 1e-6;
  const maxY = Math.max(start.y, end.y) + 1e-6;

  return (
    point.x >= minX &&
    point.x <= maxX &&
    point.y >= minY &&
    point.y <= maxY
  );
}

/**
 * Finds intersection points between a line and the edges of a polygon.
 *
 * @param {Object} line - Line with properties A, B, C.
 * @param {Array} polygonPoints - Array of point objects defining the polygon.
 * @returns {Array} Array of intersection points.
 */
function getLineIntersectionsWithPolygon(line, polygonPoints) {
  const intersections = [];
  const numPoints = polygonPoints.length;

  for (let i = 0; i < numPoints; i++) {
    const start = polygonPoints[i];
    const end = polygonPoints[(i + 1) % numPoints];

    const edgeLine = getLineFromPoints(start, end);
    const intersection = getIntersectionPoint(line, edgeLine);
    if (
      intersection &&
      isPointOnLineSegment(intersection, start, end)
    ) {
      intersections.push(intersection);
    }
  }

  return intersections;
}

/**
 * Constructs a line object from two points.
 *
 * @param {Object} p1 - Starting point.
 * @param {Object} p2 - Ending point.
 * @returns {Object} Line with properties A, B, C.
 */
function getLineFromPoints(p1, p2) {
  const A = p2.y - p1.y;
  const B = p1.x - p2.x;
  const C = -(A * p1.x + B * p1.y);
  return { A, B, C };
}

/**
 * Removes duplicate points from an array of points.
 *
 * @param {Array} points - Array of point objects with properties x and y.
 * @returns {Array} Array of unique point objects.
 */
function removeDuplicatePoints(points) {
  const unique = [];
  points.forEach((p) => {
    if (!unique.some((u) => Math.abs(u.x - p.x) < 1e-6 && Math.abs(u.y - p.y) < 1e-6)) {
      unique.push(p);
    }
  });
  return unique;
}

/**
 * Orders four points to form a quadrilateral in clockwise order.
 *
 * @param {Array} points - Array of four point objects with properties x and y.
 * @returns {Array} Ordered array of points.
 */
function orderQuadrilateralPoints(points) {
  // Calculate centroid
  const centroid = {
    x: points.reduce((sum, p) => sum + p.x, 0) / 4,
    y: points.reduce((sum, p) => sum + p.y, 0) / 4,
  };

  // Sort points by angle from centroid
  const sortedPoints = points.slice().sort((a, b) => {
    const angleA = Math.atan2(a.y - centroid.y, a.x - centroid.x);
    const angleB = Math.atan2(b.y - centroid.y, b.x - centroid.x);
    return angleA - angleB;
  });

  return sortedPoints;
}

/**
 * Determines if four points form a valid convex quadrilateral.
 *
 * @param {Array} points - Ordered array of four point objects.
 * @returns {boolean} True if valid quadrilateral, else false.
 */
function isValidQuadrilateral(points) {
  // Check for colinearity
  for (let i = 0; i < 4; i++) {
    const p1 = points[i];
    const p2 = points[(i + 1) % 4];
    const p3 = points[(i + 2) % 4];

    const area = Math.abs(
      (p1.x * (p2.y - p3.y) +
        p2.x * (p3.y - p1.y) +
        p3.x * (p1.y - p2.y)) / 2
    );
    if (area < 1e-6) {
      return false; // Points are colinear
    }
  }

  // Check convexity
  return isConvex(points);
}

/**
 * Determines if a set of points forms a convex polygon.
 *
 * @param {Array} points - Ordered array of point objects.
 * @returns {boolean} True if convex, else false.
 */
function isConvex(points) {
  const numPoints = points.length;
  let prevCrossProductZ = null;

  for (let i = 0; i < numPoints; i++) {
    const p0 = points[i];
    const p1 = points[(i + 1) % numPoints];
    const p2 = points[(i + 2) % numPoints];

    const dx1 = p1.x - p0.x;
    const dy1 = p1.y - p0.y;
    const dx2 = p2.x - p1.x;
    const dy2 = p2.y - p1.y;

    const crossProductZ = dx1 * dy2 - dy1 * dx2;

    if (Math.abs(crossProductZ) < 1e-6) {
      continue; // Colinear points
    }

    if (prevCrossProductZ === null) {
      prevCrossProductZ = crossProductZ;
    } else if (crossProductZ * prevCrossProductZ < 0) {
      return false; // Non-convex
    }
  }

  return true;
}

/**
 * Finds all polygons formed by the given lines.
 *
 * @param {Array} lines - Array of line objects with properties p1 and p2.
 * @returns {Array} Array of polygons, each polygon is an array of point objects.
 */
export function findPolygons(lines) {
  // Initialize JSTS reader and writer
  const reader = new jsts.io.WKTReader();
  const writer = new jsts.io.WKTWriter();

  // Convert lines to WKT and then to JSTS LineStrings
  const jstsLines = lines.map(line => {
    const wkt = `LINESTRING(${line.p1.x} ${line.p1.y}, ${line.p2.x} ${line.p2.y})`;
    return reader.read(wkt);
  });

  // Combine all lines into a single Geometry Collection
  const geometryFactory = new jsts.geom.GeometryFactory();
  const geomCollection = geometryFactory.createGeometryCollection(jstsLines);

  // Perform union to merge all overlapping lines
  const union = geomCollection.union();

  // Extract polygons from the union
  let polygons = [];
  if (union.getGeometryType() === 'Polygon') {
    polygons = [union];
  } else if (union.getGeometryType() === 'MultiPolygon') {
    for (let i = 0; i < union.getNumGeometries(); i++) {
      polygons.push(union.getGeometryN(i));
    }
  }

  // Convert JSTS Polygons to JS objects
  const resultPolygons = polygons.map(polygon => {
    const coords = polygon.getExteriorRing().getCoordinates();
    return coords.map(coord => ({
      x: coord.x,
      y: coord.y
    }));
  });

  return resultPolygons;
}


/**
 * Determines if a point is inside a given polygon or on its boundary using JSTS.
 *
 * @param {Object} point - Point object with properties x and y.
 * @param {Array} polygon - Array of point objects defining the polygon.
 * @returns {boolean} True if the point is inside the polygon or on its boundary, else false.
 */
export function isPointInPolygonJSTS(point, polygon) {
  const reader = new jsts.io.WKTReader();

  // Ensure the polygon is closed (first and last points are the same)
  const closedPolygon = [...polygon];
  if (closedPolygon.length > 0 && (closedPolygon[0].x !== closedPolygon[closedPolygon.length - 1].x || closedPolygon[0].y !== closedPolygon[closedPolygon.length - 1].y)) {
    closedPolygon.push({ x: closedPolygon[0].x, y: closedPolygon[0].y });
  }

  // Convert polygon to WKT
  const polygonWKT = `POLYGON((${closedPolygon.map(p => `${p.x} ${p.y}`).join(',')}))`;
  let jstsPolygon;
  try {
    jstsPolygon = reader.read(polygonWKT);
  } catch (error) {
    console.error('Invalid polygon WKT:', polygonWKT);
    return false;
  }

  // Convert point to JSTS Point
  const jstsPoint = new jsts.geom.GeometryFactory().createPoint(new jsts.geom.Coordinate(point.x, point.y));

  // Use JSTS 'covers' method to include boundary points
  return jstsPolygon.covers(jstsPoint);
}


/**
 * Finds all polygons formed by the given lines, including the border lines.
 *
 * @param {Array} lines - Array of line objects with properties p1 and p2.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Array} Array of polygons, each polygon is an array of point objects.
 */
export function getAllPolygons(lines, width, height) {
  // Initialize JSTS reader
  const reader = new jsts.io.WKTReader();
  
  // Define border lines (top, right, bottom, left)
  const borderLines = [
    { p1: { x: 0, y: 0 }, p2: { x: width, y: 0 } },           // Top
    { p1: { x: width, y: 0 }, p2: { x: width, y: height } }, // Right
    { p1: { x: width, y: height }, p2: { x: 0, y: height } }, // Bottom
    { p1: { x: 0, y: height }, p2: { x: 0, y: 0 } }          // Left
  ];

  // Combine input lines with border lines
  const allLines = [...lines, ...borderLines];

  // Convert lines to JSTS LineStrings
  const jstsLines = allLines.map(line => {
    const wkt = `LINESTRING(${line.p1.x} ${line.p1.y}, ${line.p2.x} ${line.p2.y})`;
    try {
      return reader.read(wkt);
    } catch (error) {
      console.error('Invalid LineString WKT:', wkt);
      return null;
    }
  }).filter(line => line !== null);
  
  if (jstsLines.length === 0) return [];

  // Create a Geometry Collection from all LineStrings
  const geometryFactory = new jsts.geom.GeometryFactory();
  const geomCollection = geometryFactory.createGeometryCollection(jstsLines);

  // Perform a union to merge connected lines
  const union = geomCollection.union();

  // Extract polygons from the union
  let polygons = [];
  if (union.getGeometryType() === 'Polygon') {
    polygons = [union];
  } else if (union.getGeometryType() === 'MultiPolygon') {
    for (let i = 0; i < union.getNumGeometries(); i++) {
      polygons.push(union.getGeometryN(i));
    }
  }

  // Convert JSTS Polygons to JavaScript objects
  const resultPolygons = polygons.map(polygon => {
    const coords = polygon.getExteriorRing().getCoordinates();
    // Remove the last point if it's the same as the first (closed polygon)
    if (coords.length > 1 && (coords[0].x === coords[coords.length - 1].x && coords[0].y === coords[coords.length - 1].y)) {
      coords.pop();
    }
    return coords.map(coord => ({
      x: coord.x,
      y: coord.y
    }));
  });

  return resultPolygons;
}


/**
 * Constructs a graph from input lines where vertices are intersection points (including canvas borders)
 * and edges are the line segments connecting these vertices.
 *
 * @param {Array} lines - Array of line objects with properties p1 and p2, each having x and y coordinates.
 * @param {number} width - Width of the canvas.
 * @param {number} height - Height of the canvas.
 * @returns {Object} An object containing 'nodes' and 'edges'.
 *                   - nodes: Array of vertex objects { id, x, y }.
 *                   - edges: Array of edge objects { start, end } referencing node IDs.
 */
export function constructGraph(lines, width, height) {
  const reader = new jsts.io.WKTReader();
  const factory = new jsts.geom.GeometryFactory();

  // Define border lines (top, right, bottom, left)
  const borderLines = [
    { p1: { x: 0, y: 0 }, p2: { x: width, y: 0 } },           // Top
    { p1: { x: width, y: 0 }, p2: { x: width, y: height } }, // Right
    { p1: { x: width, y: height }, p2: { x: 0, y: height } }, // Bottom
    { p1: { x: 0, y: height }, p2: { x: 0, y: 0 } }          // Left
  ];

  // Combine input lines with border lines
  const allLines = [...lines, ...borderLines];

  // Convert lines to JSTS LineStrings
  const jstsLines = allLines.map(line => {
    const wkt = `LINESTRING(${line.p1.x} ${line.p1.y}, ${line.p2.x} ${line.p2.y})`;
    try {
      return reader.read(wkt);
    } catch (error) {
      console.error('Invalid LineString WKT:', wkt);
      return null;
    }
  }).filter(line => line !== null);

  if (jstsLines.length === 0) return { nodes: [], edges: [] };

  // Create a Geometry Collection from all LineStrings
  const geomCollection = factory.createGeometryCollection(jstsLines);

  // Find all intersection points between lines
  const intersections = [];

  for (let i = 0; i < jstsLines.length; i++) {
    for (let j = i + 1; j < jstsLines.length; j++) {
      const intersect = jstsLines[i].intersection(jstsLines[j]);
      if (intersect.getNumGeometries) {
        for (let k = 0; k < intersect.getNumGeometries(); k++) {
          const geom = intersect.getGeometryN(k);
          if (geom.getGeometryType() === 'Point') {
            intersections.push({ x: geom.getX(), y: geom.getY() });
          }
        }
      } else if (intersect.getGeometryType() === 'Point') {
        intersections.push({ x: intersect.getX(), y: intersect.getY() });
      }
    }
  }

  // Remove duplicate intersection points (considering a small epsilon for floating point precision)
  const uniqueIntersections = [];
  const epsilon = 1e-6;
  intersections.forEach(pt => {
    const exists = uniqueIntersections.some(existingPt => 
      Math.abs(existingPt.x - pt.x) < epsilon && Math.abs(existingPt.y - pt.y) < epsilon
    );
    if (!exists) {
      uniqueIntersections.push(pt);
    }
  });

  // Add all line endpoints as potential vertices
  allLines.forEach(line => {
    uniqueIntersections.push(line.p1);
    uniqueIntersections.push(line.p2);
  });

  // Remove duplicates again after adding endpoints
  const finalPoints = [];
  uniqueIntersections.forEach(pt => {
    const exists = finalPoints.some(existingPt => 
      Math.abs(existingPt.x - pt.x) < epsilon && Math.abs(existingPt.y - pt.y) < epsilon
    );
    if (!exists) {
      finalPoints.push(pt);
    }
  });

  // Assign unique IDs to nodes
  const nodes = finalPoints.map((pt, index) => ({ id: index, x: pt.x, y: pt.y }));

  // Create a map for quick lookup of nodes by coordinates
  const nodeMap = new Map();
  nodes.forEach(node => {
    const key = `${node.x.toFixed(5)},${node.y.toFixed(5)}`;
    nodeMap.set(key, node.id);
  });

  // Now, for each line, split it at the intersection points and create edges between consecutive points
  const edges = [];

  allLines.forEach(line => {
    const { p1, p2 } = line;
    // Find all points on this line
    const pointsOnLine = nodes.filter(node => {
      // Check if the point lies on the line segment
      const cross = (p2.x - p1.x) * (node.y - p1.y) - (p2.y - p1.y) * (node.x - p1.x);
      if (Math.abs(cross) > epsilon) return false; // Not on the line
      const dot = (node.x - p1.x) * (p2.x - p1.x) + (node.y - p1.y) * (p2.y - p1.y);
      if (dot < 0) return false;
      const lenSq = (p2.x - p1.x) ** 2 + (p2.y - p1.y) ** 2;
      if (dot > lenSq) return false;
      return true;
    });

    // Sort points along the line
    pointsOnLine.sort((a, b) => {
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      if (Math.abs(dx) > Math.abs(dy)) {
        return a.x - b.x;
      } else {
        return a.y - b.y;
      }
    });

    // Create edges between consecutive points
    for (let i = 0; i < pointsOnLine.length - 1; i++) {
      const startPt = pointsOnLine[i];
      const endPt = pointsOnLine[i + 1];
      if (startPt.id !== endPt.id) {
        // To avoid duplicate edges, store edges in a sorted manner
        const edgeKey = startPt.id < endPt.id ? `${startPt.id}-${endPt.id}` : `${endPt.id}-${startPt.id}`;
        if (!edges.some(edge => 
          (edge.start === startPt.id && edge.end === endPt.id) ||
          (edge.start === endPt.id && edge.end === startPt.id)
        )) {
          edges.push({ start: startPt.id, end: endPt.id });
        }
      }
    }
  });

  return { nodes, edges };
}


// src/utils/utils.js

/**
 * Orders the edges cyclically around each vertex based on their angles.
 *
 * @param {Object} graph - The graph object containing 'nodes' and 'edges'.
 * @returns {Object} An object mapping each node ID to an array of connected node IDs in clockwise order.
 */
export function orderEdgesCyclically(graph) {
  const { nodes, edges } = graph;
  
  // Create a map for node ID to node data for quick lookup
  const nodeMap = new Map();
  nodes.forEach(node => nodeMap.set(node.id, node));
  
  // Initialize the ordered neighbors map
  const orderedNeighbors = {};
  
  nodes.forEach(node => {
    // Identify all edges connected to the current node
    const connectedEdges = edges.filter(edge => edge.start === node.id || edge.end === node.id);
    
    // Extract neighboring node IDs from the connected edges
    const neighbors = connectedEdges.map(edge => (edge.start === node.id ? edge.end : edge.start));
    
    // Remove duplicate neighbors to avoid redundant calculations
    const uniqueNeighbors = Array.from(new Set(neighbors));
    
    // Calculate angles for each neighbor relative to the current node
    const neighborsWithAngles = uniqueNeighbors.map(neighborId => {
      const neighbor = nodeMap.get(neighborId);
      const angle = Math.atan2(neighbor.y - node.y, neighbor.x - node.x);
      
      // Convert angle from radians to degrees and normalize to [0, 360)
      const angleDeg = (angle * 180 / Math.PI + 360) % 360;
      return { id: neighborId, angle: angleDeg };
    });
    
    // Sort neighbors by angle in ascending order (clockwise)
    neighborsWithAngles.sort((a, b) => a.angle - b.angle);
    
    // Extract sorted neighbor IDs
    const sortedNeighborIds = neighborsWithAngles.map(neighbor => neighbor.id);
    
    // Assign the sorted neighbor list to the current node in the orderedNeighbors map
    orderedNeighbors[node.id] = sortedNeighborIds;
  });
  
  return orderedNeighbors;
}

// src/utils/utils.js

/**
 * Finds all chordless cycles (polygons) in the given graph.
 *
 * @param {Object} graph - The graph object containing 'nodes' and 'edges'.
 * @param {Object} orderedEdges - An object mapping each node ID to an array of connected node IDs in clockwise order.
 * @returns {Array} Array of polygons, each polygon is an array of node objects { id, x, y }.
 */
export function findChordlessCycles(graph, orderedEdges) {
  const { nodes, edges } = graph;

  // Create a map for quick node lookup by ID
  const nodeMap = new Map();
  nodes.forEach(node => nodeMap.set(node.id, node));

  // Initialize traversal state: for each edge, track if traversed in each direction
  const traversalState = {};
  edges.forEach(edge => {
    const keyForward = `${edge.start}-${edge.end}`;
    const keyBackward = `${edge.end}-${edge.start}`;
    traversalState[keyForward] = false;
    traversalState[keyBackward] = false;
  });

  const polygons = [];

  // Helper function to get the next edge after the current one in clockwise order
  const getNextEdge = (currentNode, fromNode) => {
    const neighbors = orderedEdges[currentNode];
    if (!neighbors) return null;

    const fromIndex = neighbors.indexOf(fromNode);
    if (fromIndex === -1) return null;

    // Left turn: next neighbor in the clockwise order
    const nextIndex = (fromIndex + 1) % neighbors.length;
    return neighbors[nextIndex];
  };

  // Iterate through all edges and traverse untraversed directions
  edges.forEach(edge => {
    const directions = [
      { from: edge.start, to: edge.end, key: `${edge.start}-${edge.end}` },
      { from: edge.end, to: edge.start, key: `${edge.end}-${edge.start}` }
    ];

    directions.forEach(direction => {
      if (!traversalState[direction.key]) {
        const cycle = [];
        let currentFrom = direction.from;
        let currentTo = direction.to;
        let startFrom = currentFrom;
        let startTo = currentTo;
        let isCycle = false;

        // Begin traversing the cycle
        while (true) {
          // Mark the edge as traversed
          traversalState[`${currentFrom}-${currentTo}`] = true;
          cycle.push(currentFrom);

          // Get the next edge based on the left-turn rule
          const nextNode = getNextEdge(currentTo, currentFrom);
          if (nextNode === null) break; // Dead end, not a cycle

          // If the next edge leads back to the start, complete the cycle
          if (nextNode === startFrom) {
            cycle.push(currentTo);
            isCycle = true;
            break;
          }

          // Check if the next edge has already been traversed in this direction
          const nextEdgeKey = `${currentTo}-${nextNode}`;
          if (traversalState[nextEdgeKey]) {
            break; // Chord detected or already traversed, not a chordless cycle
          }

          // Move to the next edge
          currentFrom = currentTo;
          currentTo = nextNode;
        }

        if (isCycle) {
          // Retrieve node objects for the cycle
          const polygon = cycle.map(nodeId => nodeMap.get(nodeId));

          // Avoid duplicate polygons by checking if it's already recorded
          const polygonString = polygon.map(node => `${node.x},${node.y}`).join(' | ');
          const isDuplicate = polygons.some(existingPolygon => {
            const existingString = existingPolygon.map(node => `${node.x},${node.y}`).join(' | ');
            return existingString === polygonString;
          });

          if (!isDuplicate) {
            polygons.push(polygon);
          }
        }
      }
    });
  });

  return polygons;
}

