/**
 * Maps the number of sides to their corresponding polygon names.
 *
 * @param {number} sides - The number of sides of the polygon.
 * @returns {string} The name of the polygon.
 */
export function getPolygonName(sides) {
  const polygonNames = {
    3: 'Triangle',
    4: 'Quadrilateral',
    5: 'Pentagon',
    6: 'Hexagon',
    7: 'Heptagon',
    8: 'Octagon',
    9: 'Nonagon',
    10: 'Decagon',
    // Add more if needed
  };
  
  return polygonNames[sides] || `${sides}-gon`;
}


/**
 * Determines if a point is inside a given polygon using the ray-casting algorithm.
 *
 * @param {Object} point - Point object with properties x and y.
 * @param {Array} polygon - Array of node objects { id, x, y } defining the polygon.
 * @returns {boolean} True if the point is inside the polygon, else false.
 */
export function isPointInPolygon(point, polygon) {
  let x = point.x, y = point.y;
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    let xi = polygon[i].x, yi = polygon[i].y;
    let xj = polygon[j].x, yj = polygon[j].y;

    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-10) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

/**
 * Finds the index of the polygon that contains the given point.
 *
 * @param {Object} point - Point object with properties x and y.
 * @param {Array} polygons - Array of polygons, each polygon is an array of node objects { id, x, y }.
 * @returns {number|null} The index of the polygon that contains the point, or null if none found.
 */
export function findContainingPolygon(point, polygons) {
  for (let i = 0; i < polygons.length; i++) {
    const polygonObj = polygons[i];
    const polygon = polygonObj.vertices;
    if (isPointInPolygon(point, polygon)) {
      return polygonObj.id; // Return the unique ID
    }
  }
  return null; // No containing polygon found
}