// src/KobonMosaics.js

import React, { useState, useEffect } from 'react';
import Canvas from './components/Canvas';
import SidePanel from './components/SidePanel';
import { 
  generateRandomLines, 
  constructGraph,
  orderEdgesCyclically,
  findChordlessCycles,
  findContainingPolygon 
} from './utils/utils';
import './App.css';
import { v4 as uuidv4 } from 'uuid'; // Import UUID library for unique IDs

function KobonMosaics() {
  // State variables
  const [numLines, setNumLines] = useState(5);
  const [lines, setLines] = useState([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [borderPolygons, setBorderPolygons] = useState([]); // Stores border polygons with IDs
  const [selectedPolygonFillColor, setSelectedPolygonFillColor] = useState('#00ff00'); // Default to green
  const [showLines, setShowLines] = useState(true); // State variable to control line visibility
  const [shouldRandomizeOnUpdate, setShouldRandomizeOnUpdate] = useState(false); // Flag to trigger randomization after update

  // New state variable for 'Line at Infinity' checkbox
  const [lineAtInfinity, setLineAtInfinity] = useState(false);

  // New state variable for 'Randomly Color Border Polygons' checkbox
  const [randomizeBorderPolygons, setRandomizeBorderPolygons] = useState(true);

  // Other state variables
  const [graph, setGraph] = useState({ nodes: [], edges: [] }); 
  const [orderedEdges, setOrderedEdges] = useState({}); 
  const [polygons, setPolygons] = useState([]); // Polygons with unique IDs
  const [selectedPolygons, setSelectedPolygons] = useState({}); // Now uses polygon IDs as keys
  const [categorizedPolygons, setCategorizedPolygons] = useState({}); 
  const [polygonFillColors, setPolygonFillColors] = useState({}); 

  const MAX_LINES = 20;
  const width = 800;
  const height = 600;

  // Define polygon types up to 20 sides and add 'border'
  const polygonTypes = Array.from({ length: 18 }, (_, i) => {
    const sides = i + 3;
    let name = '';
    switch (sides) {
      case 3: name = 'Triangle'; break;
      case 4: name = 'Quadrilateral'; break;
      case 5: name = 'Pentagon'; break;
      case 6: name = 'Hexagon'; break;
      case 7: name = 'Heptagon'; break;
      case 8: name = 'Octagon'; break;
      case 9: name = 'Nonagon'; break;
      case 10: name = 'Decagon'; break;
      default: name = `${sides}-gon`;
    }
    return { sides, name };
  });
  polygonTypes.push({ sides: 'border', name: 'Border Cells' });

  // Default colors for polygon types
  const defaultColors = {
    3: '#ff0000', // Triangle - red
    4: '#00ff00', // Quadrilateral - green
    5: '#0000ff', // Pentagon - blue
    6: '#ffff00', // Hexagon - yellow
    7: '#ff00ff', // Heptagon - magenta
    8: '#00ffff', // Octagon - cyan
    9: '#ffa500', // Nonagon - orange
    10: '#800080', // Decagon - purple
    border: '#808080', // Border - gray
    // Others default to white
  };

  // Initialize polygon fill colors
  useEffect(() => {
    const initialColors = {};
    polygonTypes.forEach(({ sides }) => {
      initialColors[sides] = defaultColors[sides] || '#ffffff';
    });
    setPolygonFillColors(initialColors);
  }, []); // Run only once

  // Function to generate a random color in HEX format
  const getRandomColor = () => {
    const r = Math.floor(Math.random() * 256); // 0 to 255
    const g = Math.floor(Math.random() * 256); // 0 to 255
    const b = Math.floor(Math.random() * 256); // 0 to 255
    // Convert to hex and pad with zeros if necessary
    const toHex = (value) => value.toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  };

  // Handle Randomize Colors Button Click
  const handleRandomizeColors = () => {
    const randomColors = {};
    polygonTypes.forEach(({ sides }) => {
      randomColors[sides] = getRandomColor();
    });
    setPolygonFillColors(randomColors);
  };

  // Handle Randomize All Button Click
  const handleRandomizeAll = () => {
    const randomNumLines = Math.floor(Math.random() * (MAX_LINES - 1)) + 2; // Random number between 2 and MAX_LINES
    setNumLines(randomNumLines);

    // Generate random colors and update after lines are updated
    const randomColors = {};
    polygonTypes.forEach(({ sides }) => {
      randomColors[sides] = getRandomColor();
    });
    const randomSelectedColor = getRandomColor();

    // Set flag to randomize after polygons are updated
    setShouldRandomizeOnUpdate({
      randomizeColors: randomColors,
      selectedColor: randomSelectedColor,
    });

    // Reset selected polygons before generating new lines
    setSelectedPolygons({});
    handleGenerate(randomNumLines);
  };

  // Handle Generate Lines
  const handleGenerate = (linesCount = numLines) => {
    if (linesCount < 2 || linesCount > MAX_LINES) {
      alert(`Please enter a number between 2 and ${MAX_LINES}`);
      return;
    }
    setIsGenerating(true);

    // Generate new lines and replace old ones
    const generatedLines = generateRandomLines(linesCount, width, height);
    setLines(generatedLines);
    setIsGenerating(false);
  };

  // Handler: Update Line Endpoint
  const handleUpdateLineEndpoint = (lineIndex, endpoint, newCoord) => {
    setLines((prevLines) => {
      const updatedLines = [...prevLines];
      const lineToUpdate = { ...updatedLines[lineIndex] };
      lineToUpdate[endpoint] = newCoord;

      // Recompute line coefficients based on new p1 and p2
      const p1 = lineToUpdate.p1;
      const p2 = lineToUpdate.p2;
      const A = p2.y - p1.y;
      const B = p1.x - p2.x;
      const C = -(A * p1.x + B * p1.y);
      lineToUpdate.A = A;
      lineToUpdate.B = B;
      lineToUpdate.C = C;

      updatedLines[lineIndex] = lineToUpdate;
      return updatedLines;
    });
  };

  // Recompute Graph and Polygons Whenever Lines Change
  useEffect(() => {
    if (lines.length > 0) {
      // Step 1: Construct the graph
      const constructedGraph = constructGraph(lines, width, height);
      setGraph(constructedGraph);

      // Step 2: Order edges cyclically around each vertex
      const ordered = orderEdgesCyclically(constructedGraph);
      setOrderedEdges(ordered);

      // Step 3: Find chordless cycles (polygons)
      const foundPolygons = findChordlessCycles(constructedGraph, ordered);

      // Assign unique IDs to polygons
      const polygonsWithIDs = foundPolygons.map((polygon) => ({
        id: uuidv4(),
        vertices: polygon,
      }));

      setPolygons(polygonsWithIDs);

      // Reset selected polygons when polygons change
      setSelectedPolygons({});

      // Categorize polygons
      const newBorderPolygons = [];
      const categorized = {};

      polygonsWithIDs.forEach((polygonObj) => {
        const { vertices } = polygonObj;
        if (!Array.isArray(vertices)) return;

        let uniqueVertices = vertices;
        if (vertices.length > 1) {
          const first = vertices[0];
          const last = vertices[vertices.length - 1];
          if (first.x === last.x && first.y === last.y) {
            uniqueVertices = vertices.slice(0, -1);
          }
        }
        const sides = uniqueVertices.length;
        if (sides < 3) return;

        // Determine if the polygon is Border or Interior
        const isBorder = uniqueVertices.some((point) => {
          const epsilon = 1e-3; // Adjust epsilon as needed
          return (
            Math.abs(point.x) < epsilon ||
            Math.abs(point.x - width) < epsilon ||
            Math.abs(point.y) < epsilon ||
            Math.abs(point.y - height) < epsilon
          );
        });

        if (isBorder) {
          if (lineAtInfinity) {
            // Adjust the number of sides for border polygons
            const adjustedSides = calculateAdjustedSides(uniqueVertices);
            if (!categorized[adjustedSides]) {
              categorized[adjustedSides] = [];
            }
            categorized[adjustedSides].push(polygonObj);
          } else {
            newBorderPolygons.push(polygonObj); // Collect border polygons with IDs
          }
        } else {
          if (!categorized[sides]) {
            categorized[sides] = [];
          }
          categorized[sides].push(polygonObj);
        }
      });

      // Remove the polygon with the most sides from newBorderPolygons (outermost border)
      if (!lineAtInfinity && newBorderPolygons.length > 0) {
        let maxSides = -1;
        let maxPolygon = null;
        newBorderPolygons.forEach((polygonObj) => {
          const sides = polygonObj.vertices.length;
          if (sides > maxSides) {
            maxSides = sides;
            maxPolygon = polygonObj;
          }
        });
        if (maxPolygon) {
          const indexToRemove = newBorderPolygons.findIndex(
            (polygonObj) => polygonObj.id === maxPolygon.id
          );
          if (indexToRemove !== -1) {
            newBorderPolygons.splice(indexToRemove, 1);
          }
        }
      }

      setCategorizedPolygons(categorized);
      setBorderPolygons(lineAtInfinity ? [] : newBorderPolygons);

      // Handle randomization after polygons are updated
      if (shouldRandomizeOnUpdate) {
        // Update polygon fill colors
        setPolygonFillColors(shouldRandomizeOnUpdate.randomizeColors);
        setSelectedPolygonFillColor(shouldRandomizeOnUpdate.selectedColor);

        // Reset selected polygons
        setSelectedPolygons({});

        if (!lineAtInfinity && randomizeBorderPolygons) {
          // Randomly select border polygons only when lineAtInfinity is false and randomizeBorderPolygons is true
          const totalBorderCells = newBorderPolygons.length;
          const randomNumBorderCells = Math.floor(Math.random() * (totalBorderCells + 1)); // 0 to totalBorderCells inclusive

          const shuffledPolygons = [...newBorderPolygons].sort(() => 0.5 - Math.random());
          const selectedPolygonsArray = shuffledPolygons.slice(0, randomNumBorderCells);

          // Update selectedPolygons state using IDs
          const newSelectedPolygons = {};
          selectedPolygonsArray.forEach((polygonObj) => {
            newSelectedPolygons[polygonObj.id] = shouldRandomizeOnUpdate.selectedColor;
          });
          setSelectedPolygons(newSelectedPolygons);
        }

        // Reset the flag
        setShouldRandomizeOnUpdate(false);
      }

    } else {
      setGraph({ nodes: [], edges: [] });
      setOrderedEdges({});
      setPolygons([]);
      setCategorizedPolygons({});
      setBorderPolygons([]);
    }
  }, [lines, lineAtInfinity, randomizeBorderPolygons]); // Include randomizeBorderPolygons in dependencies

  // Function to calculate adjusted sides for border polygons
  const calculateAdjustedSides = (uniqueVertices) => {
    const epsilon = 1e-3;
    const totalSides = uniqueVertices.length;

    // Compute the edges
    const edges = [];
    for (let i = 0; i < uniqueVertices.length; i++) {
      const p1 = uniqueVertices[i];
      const p2 = uniqueVertices[(i + 1) % uniqueVertices.length];
      edges.push({ p1, p2 });
    }

    // Count the number of boundary edges
    let boundaryEdgesCount = 0;
    edges.forEach((edge) => {
      if (isEdgeOnBoundary(edge)) {
        boundaryEdgesCount++;
      }
    });

    // Treat the boundary edges as one side
    const adjustedSides = (totalSides - boundaryEdgesCount) + 1; // Boundary counted as one side

    return adjustedSides;
  };

  // Function to determine if an edge is on the boundary
  const isEdgeOnBoundary = (edge) => {
    const { p1, p2 } = edge;
    const epsilon = 1e-3;

    const isP1OnLeft = Math.abs(p1.x) < epsilon;
    const isP1OnRight = Math.abs(p1.x - width) < epsilon;
    const isP1OnTop = Math.abs(p1.y) < epsilon;
    const isP1OnBottom = Math.abs(p1.y - height) < epsilon;

    const isP2OnLeft = Math.abs(p2.x) < epsilon;
    const isP2OnRight = Math.abs(p2.x - width) < epsilon;
    const isP2OnTop = Math.abs(p2.y) < epsilon;
    const isP2OnBottom = Math.abs(p2.y - height) < epsilon;

    // Edge is on left boundary
    if (isP1OnLeft && isP2OnLeft) {
      return true;
    }

    // Edge is on right boundary
    if (isP1OnRight && isP2OnRight) {
      return true;
    }

    // Edge is on top boundary
    if (isP1OnTop && isP2OnTop) {
      return true;
    }

    // Edge is on bottom boundary
    if (isP1OnBottom && isP2OnBottom) {
      return true;
    }

    return false;
  };

  // Handle Point Selection and Polygon Detection
  const handleCanvasClick = (x, y) => {
    const point = { x, y };
    const containingPolygonID = findContainingPolygon(point, polygons);
    if (containingPolygonID) {
      setSelectedPolygons((prevSelected) => {
        if (prevSelected.hasOwnProperty(containingPolygonID)) {
          // Unselect if already selected
          const newSelected = { ...prevSelected };
          delete newSelected[containingPolygonID];
          return newSelected;
        } else {
          // Select if not already selected
          return {
            ...prevSelected,
            [containingPolygonID]: selectedPolygonFillColor, // Store the color
          };
        }
      });
    }
  };

  // Update Polygon Fill Colors
  const handlePolygonFillColorChange = (sides, color) => {
    setPolygonFillColors((prevColors) => ({
      ...prevColors,
      [sides]: color,
    }));
  };

  // Compute Maximum Possible Sides Given Number of Lines
  const maxPossibleSides = numLines;

  // Toggle line visibility
  const handleToggleLines = () => {
    setShowLines((prevShowLines) => !prevShowLines);
  };

  return (
    <div className="KobonMosaics">
      <h1>Kobon Mosaics</h1>
      <div className="controls">
        {/* Number of Lines Input */}
        <label>
          Number of Lines (2-{MAX_LINES}):
          <input
            type="number"
            value={numLines}
            onChange={(e) => setNumLines(parseInt(e.target.value, 10))}
            min="2"
            max={MAX_LINES}
          />
        </label>
        {/* Generate Button */}
        <button className="btn btn-primary" onClick={() => handleGenerate()} disabled={isGenerating}>
          {isGenerating ? 'Generating...' : 'Generate'}
        </button>
        {/* Randomize All Button */}
        <button className="btn btn-secondary" onClick={handleRandomizeAll}>
          Randomize
        </button>
        {/* Line at Infinity Checkbox */}
        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={lineAtInfinity}
            onChange={(e) => setLineAtInfinity(e.target.checked)}
          />
          Line at Infinity
        </label>
        {/* Randomly Color Border Polygons Checkbox */}
        {!lineAtInfinity && (
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={randomizeBorderPolygons}
              onChange={(e) => setRandomizeBorderPolygons(e.target.checked)}
            />
            Randomly Color Border Polygons
          </label>
        )}
        {/* Selected Polygon Color Picker */}
        <label className="color-picker-label">
          Selected Polygon Fill Color:
          <input
            type="color"
            value={selectedPolygonFillColor}
            onChange={(e) => setSelectedPolygonFillColor(e.target.value)}
          />
        </label>
        {/* Toggle Lines Button */}
        <button className="btn btn-secondary" onClick={handleToggleLines}>
          {showLines ? 'Hide Lines' : 'Show Lines'}
        </button>
      </div>
      {/* Canvas and Side Panel */}
      <div className="canvas-and-side-panel">
        {/* Canvas Component */}
        <div className="canvas-container">
          {polygons.length > 0 ? (
            <Canvas
              lines={lines}
              polygons={polygons}
              categorizedPolygons={categorizedPolygons}
              borderPolygons={borderPolygons}
              width={width}
              height={height}
              polygonFillColors={polygonFillColors}
              onUpdateLineEndpoint={handleUpdateLineEndpoint}
              onCanvasClick={handleCanvasClick}
              selectedPolygons={selectedPolygons}
              showLines={showLines}
            />
          ) : (
            <p>Loading...</p>
          )}
        </div>
        {/* Side Panel Component */}
        <SidePanel
          polygonTypes={polygonTypes}
          maxPossibleSides={maxPossibleSides}
          polygonFillColors={polygonFillColors}
          handlePolygonFillColorChange={handlePolygonFillColorChange}
          handleRandomizeColors={handleRandomizeColors}
          lineAtInfinity={lineAtInfinity} // Pass the prop
        />
      </div>
      {/* Information Display */}
      <div className="info">
        {/* Selected Polygons */}
        {Object.keys(selectedPolygons).length > 0 && (
          <div>
            <h3>Selected Polygons:</h3>
            {Object.entries(selectedPolygons).map(([polygonID, color], idx) => {
              const polygonObj = polygons.find((p) => p.id === polygonID);
              if (!polygonObj) return null; // Skip if not found
              const { vertices } = polygonObj;
              return (
                Array.isArray(vertices) && vertices.length >= 3 ? (
                  <div key={idx}>
                    <h4>Polygon {idx + 1} (Color: {color}):</h4>
                    <ul>
                      {vertices.map((point, pointIdx) => (
                        <li key={pointIdx}>
                          ({point.x.toFixed(2)}, {point.y.toFixed(2)})
                        </li>
                      ))}
                    </ul>
                  </div>
                ) : (
                  <div key={idx}>
                    <h4>Polygon {idx + 1}:</h4>
                    <p>Error: Polygon data is invalid.</p>
                  </div>
                )
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default KobonMosaics;
