// src/components/Canvas.js

import React, { useRef, useEffect, useState } from 'react';
import './Canvas.css';

const Canvas = ({ 
  lines, 
  polygons, // Polygons with IDs
  categorizedPolygons, // Polygons categorized by sides
  borderPolygons, // Polygons with IDs
  width = 800, 
  height = 600, 
  polygonFillColors, // Fill colors for each polygon type
  onUpdateLineEndpoint,
  onCanvasClick,
  selectedPolygons, // Now an object mapping polygon IDs to colors
  showLines // Prop to control line visibility
}) => {
  const canvasRef = useRef(null);
  const [dragging, setDragging] = useState(null); // { lineIndex, endpoint }

  // Helper functions...

  // Helper function to get mouse position relative to canvas
  const getMousePos = (canvas, evt) => {
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    return {
      x: (evt.clientX - rect.left) * (canvas.width / rect.width) / dpr,
      y: (evt.clientY - rect.top) * (canvas.height / rect.height) / dpr
    };
  };

  // Distance between two points
  const distance = (p1, p2) => {
    const dx = p1.x - p2.x;
    const dy = p1.y - p2.y;
    return Math.sqrt(dx * dx + dy * dy);
  };

  // Helper clamp function
  const clamp = (value, min, max) => {
    return Math.max(min, Math.min(max, value));
  };

  // Helper function to determine the side of a point
  const getSide = (x, y) => {
    const epsilon = 10; // Tolerance for border detection
    if (y <= epsilon) return 'top';
    if (y >= height - epsilon) return 'bottom';
    if (x <= epsilon) return 'left';
    if (x >= width - epsilon) return 'right';
    return ''; // Not on any side
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    // Handle high-DPI scaling
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.scale(dpr, dpr);

    // Set line properties for smoothness
    ctx.lineWidth = 1;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';

    // Clear Canvas
    ctx.clearRect(0, 0, width, height);

    // **1. Draw Categorized Polygons with Their Fill Colors**
    Object.entries(categorizedPolygons).forEach(([sides, polygonsOfSide]) => {
      const fillColor = polygonFillColors[sides];
      if (fillColor) {
        ctx.fillStyle = fillColor;
        polygonsOfSide.forEach((polygonObj) => {
          const polygon = polygonObj.vertices;
          if (!Array.isArray(polygon) || polygon.length < 3) return; // Safeguard

          ctx.beginPath();
          polygon.forEach((point, idx) => {
            if (idx === 0) {
              ctx.moveTo(point.x + 0.5, point.y + 0.5);
            } else {
              ctx.lineTo(point.x + 0.5, point.y + 0.5);
            }
          });
          ctx.closePath();
          ctx.fill();

          if (showLines) {
            ctx.strokeStyle = 'black';
          } else {
            ctx.strokeStyle = ctx.fillStyle; // Match stroke color to fill color
          }
          ctx.lineWidth = showLines ? 1 : 1; // Keep line width consistent
          ctx.stroke();
        });
      }
    });

    // **2. Draw Border Polygons with Their Fill Color**
    const borderFillColor = polygonFillColors['border'];
    if (borderPolygons && borderPolygons.length > 0 && borderFillColor) {
      ctx.fillStyle = borderFillColor; // Set fill color for border polygons
      borderPolygons.forEach((polygonObj) => {
        const polygon = polygonObj.vertices;
        if (!Array.isArray(polygon) || polygon.length < 3) return; // Safeguard

        ctx.beginPath();
        polygon.forEach((point, idx) => {
          if (idx === 0) {
            ctx.moveTo(point.x + 0.5, point.y + 0.5);
          } else {
            ctx.lineTo(point.x + 0.5, point.y + 0.5);
          }
        });
        ctx.closePath();
        ctx.fill();

        if (showLines) {
          ctx.strokeStyle = 'black';
        } else {
          ctx.strokeStyle = ctx.fillStyle; // Match stroke color to fill color
        }
        ctx.lineWidth = showLines ? 1 : 1; // Keep line width consistent
        ctx.stroke();
      });
    }

    // **3. Overlay Selected Polygons with Their Stored Colors**
    if (selectedPolygons && Object.keys(selectedPolygons).length > 0) {
      Object.entries(selectedPolygons).forEach(([polygonID, color]) => {
        const polygonObj = polygons.find((p) => p.id === polygonID);
        if (!polygonObj) return; // Skip if not found
        const polygon = polygonObj.vertices;
        if (!Array.isArray(polygon) || polygon.length < 3) {
          // Safeguard against invalid polygon structure
          return;
        }
        if (color) {
          ctx.fillStyle = color;
        } else {
          ctx.fillStyle = 'transparent';
        }
        ctx.beginPath();
        polygon.forEach((point, idx) => {
          if (idx === 0) {
            ctx.moveTo(point.x + 0.5, point.y + 0.5);
          } else {
            ctx.lineTo(point.x + 0.5, point.y + 0.5);
          }
        });
        ctx.closePath();
        ctx.fill();

        if (showLines) {
          ctx.strokeStyle = 'black';
        } else {
          ctx.strokeStyle = ctx.fillStyle; // Match stroke color to fill color
        }
        ctx.lineWidth = showLines ? 1 : 1; // Keep line width consistent
        ctx.stroke();
      });
    }

    // **4. Draw Lines on Top Using Stored Border Points (if showLines is true)**
    if (showLines) {
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 1;
      lines.forEach((line) => {
        const { p1, p2 } = line;
        ctx.beginPath();
        ctx.moveTo(p1.x + 0.5, p1.y + 0.5);
        ctx.lineTo(p2.x + 0.5, p2.y + 0.5);
        ctx.stroke();
      });
    }

  }, [lines, categorizedPolygons, borderPolygons, polygons, polygonFillColors, selectedPolygons, width, height, showLines]);

  // Event handlers...

  useEffect(() => {
    const canvas = canvasRef.current;

    const handleMouseDown = (e) => {
      const pos = getMousePos(canvas, e);
      // Only allow dragging lines if showLines is true
      if (showLines) {
        // Check if the click is near any line's endpoint
        for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const endpoints = ['p1', 'p2'];
          for (let endpoint of endpoints) {
            if (distance(pos, line[endpoint]) <= 10) { // Tolerance of 10 pixels
              setDragging({ lineIndex: i, endpoint });
              return;
            }
          }
        }
      }
    };

    const handleMouseMove = (e) => {
      if (dragging) {
        const pos = getMousePos(canvas, e);
        const { lineIndex, endpoint } = dragging;
        const line = lines[lineIndex];
        const otherEndpoint = endpoint === 'p1' ? line.p2 : line.p1;
        const otherSide = getSide(otherEndpoint.x, otherEndpoint.y);
        
        // Determine the new side based on the mouse position
        const newSide = getSide(pos.x, pos.y);

        // If newSide is empty or same as otherSide, do not allow updating
        if (!newSide || newSide === otherSide) {
          return; // Prevent moving to the same side or off the border
        }

        // Calculate new coordinates based on the new side
        let newCoord = { ...line[endpoint] };
        switch (newSide) {
          case 'top':
            newCoord.x = clamp(pos.x, 0, width);
            newCoord.y = 0;
            break;
          case 'bottom':
            newCoord.x = clamp(pos.x, 0, width);
            newCoord.y = height;
            break;
          case 'left':
            newCoord.x = 0;
            newCoord.y = clamp(pos.y, 0, height);
            break;
          case 'right':
            newCoord.x = width;
            newCoord.y = clamp(pos.y, 0, height);
            break;
          default:
            // Not on any side, do not allow dragging
            return;
        }

        // Update the line's endpoint in real-time for preview
        onUpdateLineEndpoint(lineIndex, endpoint, newCoord);
      }
    };

    const handleMouseUp = (e) => {
      if (dragging) {
        // Dragging is already handled in handleMouseMove
        setDragging(null);
      }
    };

    const handleClick = (e) => {
      const pos = getMousePos(canvas, e);
      onCanvasClick(pos.x, pos.y);
    };

    // Attach event listeners
    canvas.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    canvas.addEventListener('click', handleClick);

    // Cleanup
    return () => {
      canvas.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      canvas.removeEventListener('click', handleClick);
    };
  }, [lines, dragging, onUpdateLineEndpoint, width, height, onCanvasClick, showLines]);

  return <canvas ref={canvasRef} width={width} height={height}></canvas>;
};

export default Canvas;
