// src/components/SidePanel.js

import React from 'react';

const SidePanel = ({
  polygonTypes,
  maxPossibleSides,
  polygonFillColors,
  handlePolygonFillColorChange,
  handleRandomizeColors,
  lineAtInfinity, // Add this prop
}) => {
  return (
    <div className="side-panel">
      <h3>Polygon Fill Colors</h3>
      <div className="polygon-color-pickers">
        {/* Randomize Colors Button */}
        <button className="btn btn-secondary" onClick={handleRandomizeColors}>
          Randomize Colors
        </button>
        {/* Color Pickers for Each Polygon Type */}
        {polygonTypes.map(({ sides, name }) => {
          // Hide 'Border Cells' when lineAtInfinity is true
          if (lineAtInfinity && sides === 'border') {
            return null;
          }
          const isDisabled = sides !== 'border' && sides > maxPossibleSides;
          return (
            <label
              key={sides}
              className={`color-picker-label ${isDisabled ? 'disabled' : ''}`}
            >
              {name} Fill Color:
              <input
                type="color"
                value={polygonFillColors[sides]}
                onChange={(e) => handlePolygonFillColorChange(sides, e.target.value)}
                disabled={isDisabled}
              />
            </label>
          );
        })}
      </div>
    </div>
  );
};

export default SidePanel;
